const translations={
fr:{downloadCtaIos:'Télécharger pour iOS',iosSoon:'La version iOS arrive bientôt.',navDiscover:'Découvrir',navFeatures:'Fonctionnalités',navAbout:'À propos',navDownload:'Télécharger',eyebrow:'LE SAVOIR À PORTÉE DE MAIN',heroTitle:'Lire. Écouter.<br><em>Apprendre et transmettre.</em>',heroLead:'Une plateforme complète pour apprendre : le Saint Coran, près de 100 récitateurs, une vaste bibliothèque de livres, les hadiths, les adhkar et des outils pour progresser à votre rythme.',heroCta:'Télécharger gratuitement',heroSecondary:'Explorer les fonctionnalités',heroNote:'Application Android · Accès gratuit · Interface en 3 langues',heroBottom:'UNE RESSOURCE POUR VOTRE CHEMINEMENT',introKicker:'LA CONNAISSANCE, SIMPLEMENT',introTitle:'Un espace pour<br><em>étudier à votre rythme.</em>',introText:'Dès la première version, retrouvez plus de 23 livres et 16 grands recueils de hadith complets, soit près de 40 livres et recueils au total. Profitez également d’environ 30 cours audio de savants. La collection continuera de s’agrandir. Créez vos emplois du temps d’étude, écoutez les mutun et les récitations, et importez vos propres fichiers audio dans le lecteur intégré.',learnMore:'En savoir plus',statSurahs:'récitateurs disponibles',statReadings:'lectures · Hafs & Warsh',statBooks:'livres & recueils',statCourses:'cours audio',statLanguages:'langues d’interface',statPrice:'téléchargement gratuit',featuresKicker:'DANS L’APPLICATION',featuresTitle:'Des ressources pour<br><em>chaque étape.</em>',featuresLead:'Un environnement pensé pour la lecture, l’écoute, l’étude et la mémorisation.',fQuranTitle:'Le Saint Coran',fQuranText:'Consultez le Mushaf avec les lectures Hafs et Warsh. Retrouvez vos sourates, marque-pages et outils d’apprentissage et de révision.',fBooksTitle:'Bibliothèque de livres',fBooksText:'Explorez des ouvrages et des textes pour approfondir différentes disciplines islamiques.',fHadithTitle:'Hadiths & mutun',fHadithText:'Consultez 16 grands recueils de hadith complets, parmi les références majeures, ainsi que des textes et ressources pour les étudier.',fAudioTitle:'Écoute & récitations',fAudioText:'Un véritable lecteur audio : écoutez les mutun, des cours audio de grands savants et des récitations, et importez vos propres fichiers audio pour les écouter dans l’application.',fLangTitle:'Trois langues',fLangText:'Utilisez l’interface en arabe, en français ou en anglais selon votre préférence.',quoteText:'La régularité dans l’apprentissage commence par un accès simple aux ressources.',quoteCaption:'VOTRE ESPACE D’ÉTUDE',navSadaqa:'Sadaqa',fAdhkarTitle:'Adhkar & invocations',fAdhkarText:'Retrouvez les invocations du quotidien et la Citadelle du musulman pour nourrir votre rappel d’Allah.',fLearningTitle:'Apprendre & réviser',fLearningText:'Organisez votre mémorisation du Coran, sauvegardez vos sourates et reprenez votre progression.',fStudyTitle:'Sciences islamiques',fStudyText:'Étudiez l’aqidah, le fiqh, le tajwid, la langue arabe, l’adab et les sciences du hadith.',fNawawiTitle:'Les 40 hadiths de Nawawi',fNawawiText:'Approfondissez les grands fondements de la religion à travers un recueil incontournable.',sadaqaKicker:'UN PROJET OFFERT',sadaqaTitle:'Le savoir se partage.<br><em>Cette application est une sadaqa.</em>',sadaqaText:'الرسالة est gratuit par choix. Il a été créé pour que chacun puisse accéder aux ressources, apprendre et avancer, sans barrière financière. Si l’application vous est utile, partagez-la autour de vous : vous aiderez peut-être quelqu’un à faire un pas dans son apprentissage.',sadaqaFoot:'Gratuit · Sans abonnement · Pour tous',aboutKicker:'NOTRE INTENTION',aboutTitle:'Un outil simple,<br><em>au service du savoir.</em>',aboutText:'الرسالة rassemble dans une seule application des outils pour lire le Coran, écouter ses récitations, étudier les livres et apprendre les sciences islamiques. Le projet souhaite rendre le savoir accessible au plus grand nombre.',aboutNote:'Pourquoi est-ce gratuit ? Parce que ce projet est une sadaqa : un travail offert dans l’espoir qu’il soit utile, qu’il aide chacun à apprendre et que sa récompense perdure. Aucun abonnement ni paiement n’est demandé pour accéder à l’application.',aboutCta:'Obtenir l’application',downloadKicker:'COMMENCEZ DÈS AUJOURD’HUI',downloadTitle:'Votre bibliothèque<br><em>vous accompagne.</em>',downloadText:'Téléchargez gratuitement l’application Android et gardez vos ressources d’étude à portée de main.',downloadCta:'Télécharger pour Android',versionLabel:'Version',freeLabel:'Gratuit',installHint:'Le téléchargement s’effectue depuis GitHub Releases. Android peut demander l’autorisation d’installer une application provenant de cette source.',faqKicker:'BESOIN D’AIDE ?',faqTitle:'Questions<br><em>fréquentes.</em>',faqLead:'Quelques informations utiles avant l’installation.',faq1q:'L’application est-elle gratuite ? +',faq1a:'Oui, absolument. Toute l’application, toutes ses fonctionnalités et tous ses contenus sont gratuits. Il n’y a ni abonnement, ni achat intégré, ni version premium. Le soutien Patreon est facultatif et sert uniquement à m’aider personnellement à développer d’autres projets.',faq2q:'Comment installer le fichier APK ? +',faq2a:'Téléchargez le fichier APK depuis la page des versions GitHub, ouvrez-le sur votre téléphone Android puis autorisez l’installation si Android vous le demande.',faq3q:'L’application fonctionne-t-elle sans Internet ? +',faq3a:'Certaines fonctions et ressources sont disponibles localement, tandis que les contenus en streaming et certaines ressources nécessitent une connexion Internet.',faq4q:'Où trouver les nouvelles versions ? +',faq4a:'Les mises à jour sont publiées dans la section Releases du dépôt GitHub officiel.',navSupport:'Soutenir',supportKicker:'SOUTIEN FACULTATIF',supportTitle:'الرسالة est gratuit. <em>Et le restera.</em>',supportText:'L’application est entièrement gratuite : toutes ses fonctionnalités et tous ses contenus sont accessibles sans abonnement, sans paiement et sans formule premium. Le Patreon n’a aucun lien avec l’accès à l’application. Si vous choisissez de me soutenir, votre contribution m’aidera personnellement à développer d’autres projets. C’est un geste totalement facultatif, simplement pour m’encourager.',supportPoint1:'Aucun contenu payant',supportPoint2:'Aucun avantage réservé aux donateurs',supportPoint3:'Soutien libre, si vous le souhaitez',supportCta:'Me soutenir sur Patreon',supportNote:'Merci pour votre soutien. Il n’est jamais nécessaire pour utiliser الرسالة.',supportLinkMissing:'Le lien Patreon sera ajouté avant la publication du site.',contactKicker:'PARTICIPER AU PROJET',contactTitle:'Une idée pour améliorer l’application ?',contactText:'Vous avez une idée, une suggestion ou vous avez repéré un bug ? Envoyez-moi un e-mail à tout moment. Vos retours m’aideront à améliorer l’application.',contactCta:'Envoyer une idée ou signaler un bug',fTafsirTitle:'Tafsir verset par verset',fTafsirText:'Consultez l’explication des versets du Coran directement depuis la lecture, pour approfondir votre compréhension.',latestUpdate:'Dernière mise à jour : 0.21.8 — accès au tafsir des versets du Coran et améliorations de l’application.',footerText:'Un espace de lecture, d’apprentissage et de révision.',footerDownload:'Télécharger gratuitement ↗',footerFree:'Projet gratuit · Android',backTop:'Retour en haut ↑'},
en:{downloadCtaIos:'Download for iOS',iosSoon:'The iOS version is coming soon.',navDiscover:'Discover',navFeatures:'Features',navAbout:'About',navDownload:'Download',eyebrow:'KNOWLEDGE WITHIN REACH',heroTitle:'Read. Listen.<br><em>Learn and share.</em>',heroLead:'A complete learning space: the Holy Quran, nearly 100 reciters, an extensive book collection, hadith, daily supplications and tools to help you progress.',heroCta:'Download for free',heroSecondary:'Explore features',heroNote:'Android app · Free access · 3 interface languages',heroBottom:'A RESOURCE FOR YOUR JOURNEY',introKicker:'KNOWLEDGE, MADE SIMPLE',introTitle:'A space to<br><em>learn at your own pace.</em>',introText:'From the very first version, explore more than 23 books and 16 complete major hadith collections — nearly 40 books and collections in total. There are also around 30 audio lessons by scholars. The library will continue to grow. Create study schedules, listen to classical texts (mutun) and recitations, and import your own audio files into the built-in player.',learnMore:'Learn more',statSurahs:'available reciters',statReadings:'readings · Hafs & Warsh',statBooks:'books & collections',statCourses:'audio lessons',statLanguages:'interface languages',statPrice:'free download',featuresKicker:'INSIDE THE APP',featuresTitle:'Resources for<br><em>every step.</em>',featuresLead:'An environment designed for reading, listening, studying and memorisation.',fQuranTitle:'The Holy Quran',fQuranText:'Read the Mushaf in Hafs and Warsh. Find your surahs, bookmarks and learning and revision tools.',fBooksTitle:'Book library',fBooksText:'Explore books and texts covering different Islamic disciplines.',fHadithTitle:'Hadith & classical texts',fHadithText:'Explore 16 complete major hadith collections, alongside reference texts and resources to study them.',fAudioTitle:'Audio & recitations',fAudioText:'A complete audio player: listen to classical texts (mutun), audio lessons by renowned scholars and recitations, and import your own audio files to play them in the app.',fLangTitle:'Three languages',fLangText:'Use the interface in Arabic, French or English.',quoteText:'Consistency in learning begins with simple access to resources.',quoteCaption:'YOUR STUDY SPACE',navSadaqa:'Sadaqah',fAdhkarTitle:'Adhkar & supplications',fAdhkarText:'Find daily supplications and the Fortress of the Muslim to keep remembrance close.',fLearningTitle:'Learn & revise',fLearningText:'Organise Quran memorisation, save surahs and continue where you left off.',fStudyTitle:'Islamic sciences',fStudyText:'Explore aqidah, fiqh, tajwid, Arabic, adab and hadith sciences.',fNawawiTitle:'The 40 Hadith of Nawawi',fNawawiText:'Study foundational teachings of the religion through this well-known collection.',sadaqaKicker:'A GIFT FOR EVERYONE',sadaqaTitle:'Knowledge is meant to be shared.<br><em>This app is a sadaqah.</em>',sadaqaText:'الرسالة is free by choice. It was created so everyone can access resources, learn and progress without a financial barrier. If you find it useful, share it with others: you may help someone take a step forward in their learning.',sadaqaFoot:'Free · No subscription · For everyone',aboutKicker:'OUR PURPOSE',aboutTitle:'A simple tool,<br><em>in service of knowledge.</em>',aboutText:'الرسالة brings together tools to read the Quran, listen to recitations, study books and learn Islamic sciences. The project aims to make knowledge accessible to as many people as possible.',aboutNote:'Why is it free? Because this project is a sadaqah: a work offered in the hope that it benefits people, helps them learn and continues to bring reward. No subscription or payment is required to access the app.',aboutCta:'Get the app',downloadKicker:'GET STARTED TODAY',downloadTitle:'Your library,<br><em>wherever you go.</em>',downloadText:'Download the free Android app and keep your study resources close at hand.',downloadCta:'Download for Android',versionLabel:'Version',freeLabel:'Free',installHint:'The download is provided through GitHub Releases. Android may ask you to allow installation from this source.',faqKicker:'NEED HELP?',faqTitle:'Frequently<br><em>asked questions.</em>',faqLead:'A few useful details before installing.',faq1q:'Is the app free? +',faq1a:'Yes, completely. The entire app, every feature and all its content are free. There are no subscriptions, in-app purchases or premium version. Patreon support is optional and only helps me personally create other projects.',faq2q:'How do I install the APK? +',faq2a:'Download the APK from the GitHub Releases page, open it on your Android phone and allow installation if Android asks you to.',faq3q:'Does the app work offline? +',faq3a:'Some features and resources are available locally, while streaming content and certain resources require an Internet connection.',faq4q:'Where can I find new versions? +',faq4a:'Updates are published in the Releases section of the official GitHub repository.',navSupport:'Support',supportKicker:'OPTIONAL SUPPORT',supportTitle:'الرسالة is free. <em>And it will stay that way.</em>',supportText:'The app is completely free: every feature and all content are available without a subscription, payment or premium plan. Patreon has absolutely no connection to access to the app. If you choose to support me, your contribution will personally help me create other projects. It is entirely optional, simply a way to encourage me.',supportPoint1:'No paid content',supportPoint2:'No donor-only features',supportPoint3:'Support only if you wish',supportCta:'Support me on Patreon',supportNote:'Thank you for your support. It is never required to use الرسالة.',supportLinkMissing:'The Patreon link will be added before the website is published.',contactKicker:'HELP SHAPE THE PROJECT',contactTitle:'Have an idea to improve the app?',contactText:'Have an idea, a suggestion or found a bug? Email me at any time. Your feedback will help me improve the app.',contactCta:'Send an idea or report a bug',fTafsirTitle:'Verse-by-verse Tafsir',fTafsirText:'Read the explanation of Quranic verses directly while reading, and deepen your understanding.',latestUpdate:'Latest update: 0.21.8 — Quran verse tafsir and app improvements.',footerText:'A space for reading, learning and revision.',footerDownload:'Download for free ↗',footerFree:'Free project · Android',backTop:'Back to top ↑'},
ar:{downloadCtaIos:'تحميل لنظام iOS',iosSoon:'نسخة iOS ستتوفر قريباً.',navDiscover:'اكتشف',navFeatures:'المميزات',navAbout:'عن التطبيق',navDownload:'تحميل',eyebrow:'العِلْمُ بَيْنَ يَدَيْكَ',heroTitle:'اقرأ. استمع.<br><em>تعلّم وانشر العلم.</em>',heroLead:'مساحة متكاملة للتعلّم: القرآن الكريم ونحو مئة قارئ ومجموعة كبيرة من الكتب والأحاديث والأذكار وأدوات تساعدك على التقدّم.',heroCta:'تحميل مجاني',heroSecondary:'اكتشف المميزات',heroNote:'تطبيق أندرويد · مجاني · الواجهة بثلاث لغات',heroBottom:'الرسالة يعينك في رحلتك',introKicker:'المعرفة ببساطة',introTitle:'مساحة<br><em>للتعلّم على مهل.</em>',introText:'منذ الإصدار الأول، يضم التطبيق أكثر من 23 كتابًا و16 مجموعة كاملة من كبار كتب الحديث، أي ما يقارب 40 كتابًا ومجموعة حديث. كما يضم نحو 30 درسًا صوتيًا للعلماء. وستتوسع المكتبة باستمرار. يمكنك إنشاء جداول للدراسة، والاستماع إلى المتون والتلاوات، واستيراد ملفاتك الصوتية إلى المشغّل المدمج.',learnMore:'اعرف المزيد',statSurahs:'قارئ متاح',statReadings:'روايتان · حفص وورش',statBooks:'كتابًا ومجموعة',statCourses:'درسًا صوتيًا',statLanguages:'لغات للواجهة',statPrice:'تحميل مجاني',featuresKicker:'داخل التطبيق',featuresTitle:'موارد لكل<br><em>مرحلة.</em>',featuresLead:'بيئة للقراءة والاستماع والدراسة والحفظ.',fQuranTitle:'القرآن الكريم',fQuranText:'تصفّح المصحف بروايتي حفص وورش، واستفد من السور والعلامات المرجعية وأدوات التعلّم والمراجعة.',fBooksTitle:'مكتبة الكتب',fBooksText:'اكتشف الكتب والمتون في مختلف العلوم الإسلامية.',fHadithTitle:'الأحاديث والمتون',fHadithText:'اطّلع على 16 مجموعة كاملة من كبار كتب الحديث، إلى جانب المتون والمراجع وموارد دراستها.',fAudioTitle:'الصوتيات والتلاوات',fAudioText:'مشغّل صوتي متكامل للاستماع إلى المتون والدروس الصوتية لكبار العلماء والتلاوات، مع إمكانية استيراد ملفاتك الصوتية الخاصة والاستماع إليها داخل التطبيق.',fLangTitle:'ثلاث لغات',fLangText:'استخدم الواجهة بالعربية أو الفرنسية أو الإنجليزية.',quoteText:'المداومة على التعلّم تبدأ بسهولة الوصول إلى المصادر.',quoteCaption:'مساحة تعلّمك',navSadaqa:'صدقة',fAdhkarTitle:'الأذكار والأدعية',fAdhkarText:'تعرّف على أذكار اليوم والليلة وحصن المسلم للمداومة على ذكر الله.',fLearningTitle:'التعلّم والمراجعة',fLearningText:'نظّم حفظ القرآن، واحفظ السور، وتابع مراجعتك من حيث توقفت.',fStudyTitle:'العلوم الإسلامية',fStudyText:'تعلّم العقيدة والفقه والتجويد واللغة العربية والأدب وعلوم الحديث.',fNawawiTitle:'الأربعون النووية',fNawawiText:'تعرّف على أصول عظيمة من الدين من خلال هذا المتن المشهور.',sadaqaKicker:'مشروع هدية للجميع',sadaqaTitle:'العلم يُتداول ويُنتفع به.<br><em>هذا التطبيق صدقة.</em>',sadaqaText:'الرسالة مجاني عن اختيار. أُنشئ ليتمكن الجميع من الوصول إلى المصادر والتعلّم والتقدّم دون عائق مادي. إذا نفعك التطبيق، فشاركه مع غيرك؛ فقد تساعد شخصًا على خطوة في طريق العلم.',sadaqaFoot:'مجاني · بلا اشتراك · للجميع',aboutKicker:'غايتنا',aboutTitle:'أداة يسيرة،<br><em>في خدمة العلم.</em>',aboutText:'يجمع الرسالة أدوات لقراءة القرآن والاستماع إلى تلاواته ودراسة الكتب وتعلّم العلوم الإسلامية. ويهدف المشروع إلى جعل العلم متاحًا لأكبر عدد ممكن من الناس.',aboutNote:'لماذا التطبيق مجاني؟ لأنه صدقة يُرجى أن تنفع الناس وتعينهم على التعلّم ويستمر أجرها. لا يحتاج الوصول إلى التطبيق إلى اشتراك أو دفع.',aboutCta:'احصل على التطبيق',downloadKicker:'ابدأ اليوم',downloadTitle:'مكتبتك<br><em>معك أينما كنت.</em>',downloadText:'حمّل تطبيق أندرويد مجانًا واجعل موارد التعلّم قريبة منك.',downloadCta:'تحميل لنظام Android',versionLabel:'الإصدار',freeLabel:'مجاني',installHint:'يتم التحميل عبر GitHub Releases. قد يطلب أندرويد السماح بتثبيت تطبيق من هذا المصدر.',faqKicker:'هل تحتاج إلى مساعدة؟',faqTitle:'أسئلة<br><em>شائعة.</em>',faqLead:'معلومات مفيدة قبل التثبيت.',faq1q:'هل التطبيق مجاني؟ +',faq1a:'نعم، التطبيق مجاني بالكامل بجميع ميزاته ومحتوياته. لا توجد اشتراكات أو مشتريات داخل التطبيق أو نسخة مدفوعة. دعم Patreon اختياري، ويساعدني شخصيًا على تطوير مشاريع أخرى فقط.',faq2q:'كيف أثبّت ملف APK؟ +',faq2a:'حمّل ملف APK من صفحة إصدارات GitHub، ثم افتحه على هاتف أندرويد واسمح بالتثبيت إذا طلب النظام ذلك.',faq3q:'هل يعمل التطبيق دون إنترنت؟ +',faq3a:'تتوفر بعض الوظائف والموارد محليًا، بينما يحتاج البث وبعض الموارد إلى اتصال بالإنترنت.',faq4q:'أين أجد الإصدارات الجديدة؟ +',faq4a:'تُنشر التحديثات في قسم Releases بمستودع GitHub الرسمي.',navSupport:'الدعم',supportKicker:'دعم اختياري',supportTitle:'تطبيق الرسالة مجاني. <em>وسيظل كذلك.</em>',supportText:'التطبيق مجاني بالكامل: جميع الميزات والمحتويات متاحة دون اشتراك أو دفع أو باقة مدفوعة. لا علاقة لصفحة Patreon بإمكانية استخدام التطبيق. إذا اخترت دعمي، فستساعدني مساهمتك شخصيًا على تطوير مشاريع أخرى. هذا الدعم اختياري تمامًا، وهو مجرد تشجيع لي.',supportPoint1:'لا يوجد محتوى مدفوع',supportPoint2:'لا مزايا خاصة للمتبرعين',supportPoint3:'الدعم اختياري لمن يرغب',supportCta:'ادعمني على Patreon',supportNote:'شكرًا لدعمكم. لا يلزم الدعم لاستخدام الرسالة.',supportLinkMissing:'ستتم إضافة رابط Patreon قبل نشر الموقع.',contactKicker:'ساهم في تطوير المشروع',contactTitle:'هل لديك فكرة لتطوير التطبيق؟',contactText:'هل لديك فكرة أو اقتراح أو وجدت خطأً في التطبيق؟ أرسل إليّ بريدًا إلكترونيًا في أي وقت. ستساعدني ملاحظاتك على تحسين التطبيق.',contactCta:'أرسل اقتراحًا أو أبلغ عن خطأ',fTafsirTitle:'تفسير الآيات آيةً آية',fTafsirText:'اقرأ تفسير آيات القرآن مباشرة أثناء التلاوة لتعميق فهمك.',latestUpdate:'آخر تحديث: 0.21.8 — إضافة تفسير آيات القرآن وتحسينات للتطبيق.',footerText:'مساحة للقراءة والتعلّم والمراجعة.',footerDownload:'تحميل مجاني ↗',footerFree:'مشروع مجاني · أندرويد',backTop:'العودة للأعلى ↑'},
es:{"navDiscover":"Descubrir","navFeatures":"Funciones","navAbout":"Acerca de","navDownload":"Descargar","eyebrow":"EL CONOCIMIENTO A TU ALCANCE","heroTitle":"Lee. Escucha.<br><em>Aprende y comparte.</em>","heroLead":"Un espacio completo de aprendizaje: el Noble Corán, casi 100 recitadores, una amplia colección de libros, hadices, súplicas diarias y herramientas para progresar.","heroCta":"Descargar gratis","heroSecondary":"Explorar funciones","heroNote":"Aplicación Android · Acceso gratuito · 8 idiomas de interfaz","heroBottom":"UN RECURSO PARA TU CAMINO","introKicker":"EL CONOCIMIENTO, MÁS SENCILLO","introTitle":"Un espacio para<br><em>aprender a tu ritmo.</em>","introText":"Desde la primera versión, encontrarás más de 23 libros y 16 grandes colecciones completas de hadices: casi 40 libros y colecciones en total. También hay unos 30 cursos de audio impartidos por eruditos. La biblioteca seguirá creciendo. Organiza tus horarios de estudio, escucha textos clásicos (mutun) y recitaciones, e importa tus propios archivos de audio al reproductor integrado.","learnMore":"Saber más","statSurahs":"recitadores disponibles","statReadings":"lecturas · Hafs y Warsh","statBooks":"libros y colecciones","statCourses":"clases de audio","statLanguages":"idiomas de interfaz","statPrice":"descarga gratuita","featuresKicker":"DENTRO DE LA APLICACIÓN","featuresTitle":"Recursos para<br><em>cada etapa.</em>","featuresLead":"Un entorno pensado para leer, escuchar, estudiar y memorizar.","fQuranTitle":"El Sagrado Corán","fQuranText":"Lee el Mushaf según las lecturas Hafs y Warsh. Encuentra tus suras, marcadores y herramientas de aprendizaje y repaso.","fBooksTitle":"Biblioteca de libros","fBooksText":"Explora libros y textos de distintas disciplinas islámicas.","fHadithTitle":"Hadices y textos clásicos","fHadithText":"Explora 16 grandes colecciones completas de hadices, junto con textos de referencia y recursos para estudiarlos.","fAudioTitle":"Audio y recitaciones","fAudioText":"Un reproductor de audio completo: escucha textos clásicos (mutun), lecciones de eruditos reconocidos y recitaciones; también puedes importar tus propios archivos de audio.","fLangTitle":"Ocho idiomas","fLangText":"Utiliza la interfaz en árabe, francés, inglés, español, alemán, portugués, turco e indonesio.","quoteText":"La constancia en el aprendizaje comienza con un acceso sencillo a los recursos.","quoteCaption":"TU ESPACIO DE ESTUDIO","navSadaqa":"Sadaqa","fAdhkarTitle":"Adhkar y súplicas","fAdhkarText":"Encuentra las súplicas diarias y la Fortaleza del musulmán para mantener vivo el recuerdo de Allah.","fLearningTitle":"Aprender y repasar","fLearningText":"Organiza la memorización del Corán, guarda suras y continúa donde lo dejaste.","fStudyTitle":"Ciencias islámicas","fStudyText":"Explora aqida, fiqh, tajwid, árabe, adab y ciencias del hadiz.","fNawawiTitle":"Los 40 hadices de Nawawi","fNawawiText":"Estudia enseñanzas fundamentales de la religión a través de esta conocida colección.","sadaqaKicker":"UN REGALO PARA TODOS","sadaqaTitle":"El conocimiento se comparte.<br><em>Esta aplicación es una sadaqa.</em>","sadaqaText":"الرسالة es gratuita por elección. Se creó para que todos puedan acceder a recursos, aprender y progresar sin barreras económicas. Si te resulta útil, compártela: puedes ayudar a alguien a avanzar en su aprendizaje.","sadaqaFoot":"Gratis · Sin suscripción · Para todos","aboutKicker":"NUESTRO PROPÓSITO","aboutTitle":"Una herramienta sencilla,<br><em>al servicio del conocimiento.</em>","aboutText":"الرسالة reúne herramientas para leer el Corán, escuchar recitaciones, estudiar libros y aprender ciencias islámicas. El proyecto busca hacer accesible el conocimiento al mayor número de personas.","aboutNote":"¿Por qué es gratis? Porque este proyecto es una sadaqa: una obra ofrecida con la esperanza de beneficiar a las personas, ayudarlas a aprender y seguir generando recompensa. No se necesita suscripción ni pago para usar la aplicación.","aboutCta":"Obtener la aplicación","downloadKicker":"EMPIEZA HOY","downloadTitle":"Tu biblioteca,<br><em>vayas donde vayas.</em>","downloadText":"Descarga gratis la aplicación Android y lleva tus recursos de estudio contigo.","downloadCta":"Descargar APK gratis","versionLabel":"Versión","freeLabel":"Gratis","installHint":"La descarga se ofrece mediante GitHub Releases. Android puede pedirte permiso para instalar aplicaciones desde esta fuente.","faqKicker":"¿NECESITAS AYUDA?","faqTitle":"Preguntas<br><em>frecuentes.</em>","faqLead":"Algunos detalles útiles antes de instalar.","faq1q":"¿La aplicación es gratuita? +","faq1a":"Sí, completamente. Toda la aplicación, sus funciones y contenidos son gratuitos. No hay suscripciones, compras dentro de la aplicación ni versión prémium. El apoyo en Patreon es opcional y me ayuda personalmente a crear otros proyectos.","faq2q":"¿Cómo instalo el APK? +","faq2a":"Descarga el APK desde GitHub Releases, ábrelo en tu teléfono Android y permite la instalación si Android te lo solicita.","faq3q":"¿Funciona sin conexión? +","faq3a":"Algunas funciones y recursos están disponibles localmente, mientras que el contenido en streaming y ciertos recursos requieren conexión a Internet.","faq4q":"¿Dónde encuentro nuevas versiones? +","faq4a":"Las actualizaciones se publican en la sección Releases del repositorio oficial de GitHub.","navSupport":"Apoyar","supportKicker":"APOYO OPCIONAL","supportTitle":"الرسالة es gratuita. <em>Y seguirá siéndolo.</em>","supportText":"La aplicación es totalmente gratuita: todas las funciones y contenidos están disponibles sin suscripción, pago ni plan prémium. Patreon no tiene ninguna relación con el acceso a la aplicación. Si decides apoyarme, tu contribución me ayudará personalmente a crear otros proyectos. Es totalmente opcional, simplemente una forma de animarme.","supportPoint1":"Sin contenido de pago","supportPoint2":"Sin funciones exclusivas para donantes","supportPoint3":"Apoya solo si lo deseas","supportCta":"Apóyame en Patreon","supportNote":"Gracias por tu apoyo. Nunca es necesario apoyar para usar الرسالة.","supportLinkMissing":"El enlace de Patreon se añadirá antes de publicar el sitio.","contactKicker":"AYUDA A MEJORAR EL PROYECTO","contactTitle":"¿Tienes una idea para mejorar la aplicación?","contactText":"¿Tienes una idea, una sugerencia o has encontrado un error? Escríbeme cuando quieras. Tus comentarios me ayudarán a mejorar la aplicación.","contactCta":"Enviar una idea o informar de un error","footerText":"Un espacio para leer, aprender y repasar.","footerDownload":"Descargar gratis ↗","footerFree":"Proyecto gratuito · Android","backTop":"Volver arriba ↑","fTafsirTitle":"Tafsir de cada versículo","fTafsirText":"Consulta la explicación de los versículos del Corán directamente durante la lectura.","latestUpdate":"Última actualización: 0.21.8 — tafsir de los versículos del Corán y mejoras de la aplicación."},
de:{"navDiscover":"Entdecken","navFeatures":"Funktionen","navAbout":"Über uns","navDownload":"Herunterladen","eyebrow":"WISSEN IN REICHWEITE","heroTitle":"Lesen. Hören.<br><em>Lernen und weitergeben.</em>","heroLead":"Ein umfassender Lernort: der Heilige Koran, fast 100 Rezitatoren, eine große Büchersammlung, Hadithe, tägliche Bittgebete und Werkzeuge für deinen Lernfortschritt.","heroCta":"Kostenlos herunterladen","heroSecondary":"Funktionen entdecken","heroNote":"Android-App · Kostenloser Zugang · 8 Oberflächensprachen","heroBottom":"EINE BEGLEITUNG AUF DEINEM WEG","introKicker":"WISSEN, EINFACH GEMACHT","introTitle":"Ein Ort zum<br><em>Lernen im eigenen Tempo.</em>","introText":"Entdecke mehr als 23 Bücher und 16 vollständige große Hadith-Sammlungen – insgesamt fast 40 Bücher und Sammlungen. Außerdem gibt es rund 30 Audio-Unterrichtseinheiten von Gelehrten. Die Bibliothek wird weiter wachsen. Erstelle Lernpläne, höre klassische Texte (Mutun) und Rezitationen und importiere eigene Audiodateien in den integrierten Player.","learnMore":"Mehr erfahren","statSurahs":"verfügbare Rezitatoren","statReadings":"Lesarten · Hafs & Warsh","statBooks":"Bücher und Sammlungen","statCourses":"Audio-Unterrichtseinheiten","statLanguages":"Oberflächensprachen","statPrice":"Kostenloser Download","featuresKicker":"IN DER APP","featuresTitle":"Ressourcen für<br><em>jeden Schritt.</em>","featuresLead":"Eine Umgebung zum Lesen, Hören, Lernen und Auswendiglernen.","fQuranTitle":"Der Heilige Koran","fQuranText":"Lies den Mushaf in den Lesarten Hafs und Warsh. Finde Suren, Lesezeichen sowie Lern- und Wiederholungswerkzeuge.","fBooksTitle":"Bücherbibliothek","fBooksText":"Entdecke Bücher und Texte aus verschiedenen islamischen Fachgebieten.","fHadithTitle":"Hadithe & klassische Texte","fHadithText":"Entdecke 16 vollständige große Hadith-Sammlungen sowie wichtige Referenztexte und Lernmaterialien.","fAudioTitle":"Audio & Rezitationen","fAudioText":"Ein vollständiger Audioplayer: Höre klassische Texte (Mutun), Unterrichtseinheiten bekannter Gelehrter und Rezitationen. Importiere auch eigene Audiodateien.","fLangTitle":"Acht Sprachen","fLangText":"Nutze die Oberfläche auf Arabisch, Französisch, Englisch, Spanisch, Deutsch, Portugiesisch, Türkisch oder Indonesisch.","quoteText":"Regelmäßiges Lernen beginnt mit einem einfachen Zugang zu den Ressourcen.","quoteCaption":"DEIN LERNBEREICH","navSadaqa":"Sadaqa","fAdhkarTitle":"Adhkar & Bittgebete","fAdhkarText":"Finde tägliche Bittgebete und die Festung des Muslims, um Allahs zu gedenken.","fLearningTitle":"Lernen & Wiederholen","fLearningText":"Organisiere das Auswendiglernen des Korans, speichere Suren und setze dort fort, wo du aufgehört hast.","fStudyTitle":"Islamische Wissenschaften","fStudyText":"Entdecke Aqida, Fiqh, Tajwid, Arabisch, Adab und Hadith-Wissenschaften.","fNawawiTitle":"Die 40 Hadithe von Nawawi","fNawawiText":"Lerne grundlegende Lehren des Islam anhand dieser bekannten Sammlung.","sadaqaKicker":"EIN GESCHENK FÜR ALLE","sadaqaTitle":"Wissen ist zum Teilen da.<br><em>Diese App ist eine Sadaqa.</em>","sadaqaText":"الرسالة ist bewusst kostenlos. Sie wurde geschaffen, damit alle ohne finanzielle Hürden auf Ressourcen zugreifen, lernen und Fortschritte machen können. Wenn sie dir hilft, teile sie mit anderen.","sadaqaFoot":"Kostenlos · Kein Abonnement · Für alle","aboutKicker":"UNSER ZIEL","aboutTitle":"Ein einfaches Werkzeug,<br><em>im Dienst des Wissens.</em>","aboutText":"الرسالة vereint Werkzeuge zum Lesen des Korans, Hören von Rezitationen, Studieren von Büchern und Lernen islamischer Wissenschaften. Das Projekt möchte Wissen möglichst vielen Menschen zugänglich machen.","aboutNote":"Warum ist die App kostenlos? Weil dieses Projekt eine Sadaqa ist: eine Arbeit in der Hoffnung, Menschen zu nützen, beim Lernen zu helfen und fortdauernden Lohn zu bringen. Für den Zugang zur App ist kein Abonnement und keine Zahlung erforderlich.","aboutCta":"App erhalten","downloadKicker":"HEUTE LOSLEGEN","downloadTitle":"Deine Bibliothek,<br><em>überall dabei.</em>","downloadText":"Lade die kostenlose Android-App herunter und habe deine Lernressourcen immer griffbereit.","downloadCta":"Kostenlose APK herunterladen","versionLabel":"Version","freeLabel":"Kostenlos","installHint":"Der Download erfolgt über GitHub Releases. Android kann dich auffordern, die Installation aus dieser Quelle zu erlauben.","faqKicker":"BRAUCHST DU HILFE?","faqTitle":"Häufig<br><em>gestellte Fragen.</em>","faqLead":"Einige hilfreiche Informationen vor der Installation.","faq1q":"Ist die App kostenlos? +","faq1a":"Ja, vollständig. Die gesamte App mit allen Funktionen und Inhalten ist kostenlos. Es gibt keine Abonnements, In-App-Käufe oder Premium-Version. Unterstützung über Patreon ist freiwillig und hilft mir persönlich bei anderen Projekten.","faq2q":"Wie installiere ich die APK? +","faq2a":"Lade die APK von GitHub Releases herunter, öffne sie auf deinem Android-Telefon und erlaube die Installation, falls Android danach fragt.","faq3q":"Funktioniert die App offline? +","faq3a":"Einige Funktionen und Ressourcen sind lokal verfügbar; Streaming-Inhalte und bestimmte Ressourcen benötigen eine Internetverbindung.","faq4q":"Wo finde ich neue Versionen? +","faq4a":"Updates werden im Bereich Releases des offiziellen GitHub-Repositorys veröffentlicht.","navSupport":"Unterstützen","supportKicker":"FREIWILLIGE UNTERSTÜTZUNG","supportTitle":"الرسالة ist kostenlos. <em>Und das bleibt so.</em>","supportText":"Die App ist vollständig kostenlos: Alle Funktionen und Inhalte sind ohne Abonnement, Zahlung oder Premium-Angebot verfügbar. Patreon hat keinerlei Einfluss auf den Zugang zur App. Wenn du mich unterstützt, hilft dein Beitrag mir persönlich, andere Projekte zu erstellen. Die Unterstützung ist völlig freiwillig.","supportPoint1":"Keine kostenpflichtigen Inhalte","supportPoint2":"Keine exklusiven Funktionen für Unterstützer","supportPoint3":"Nur unterstützen, wenn du möchtest","supportCta":"Mich auf Patreon unterstützen","supportNote":"Vielen Dank für deine Unterstützung. Sie ist niemals Voraussetzung für die Nutzung von الرسالة.","supportLinkMissing":"Der Patreon-Link wird vor der Veröffentlichung der Website hinzugefügt.","contactKicker":"HILF MIT, DAS PROJEKT ZU GESTALTEN","contactTitle":"Hast du eine Idee zur Verbesserung der App?","contactText":"Hast du eine Idee, einen Vorschlag oder einen Fehler entdeckt? Schreib mir jederzeit. Dein Feedback hilft mir, die App zu verbessern.","contactCta":"Idee senden oder Fehler melden","footerText":"Ein Ort zum Lesen, Lernen und Wiederholen.","footerDownload":"Kostenlos herunterladen ↗","footerFree":"Kostenloses Projekt · Android","backTop":"Nach oben ↑","fTafsirTitle":"Tafsir zu jedem Vers","fTafsirText":"Rufe die Erklärung der Koranverse direkt beim Lesen auf.","latestUpdate":"Letztes Update: 0.21.8 — Tafsir zu den Koranversen und Verbesserungen der App."},
pt:{"navDiscover":"Explorar","navFeatures":"Funcionalidades","navAbout":"Sobre","navDownload":"Descarregar","eyebrow":"CONHECIMENTO AO SEU ALCANCE","heroTitle":"Leia. Ouça.<br><em>Aprenda e partilhe.</em>","heroLead":"Um espaço completo de aprendizagem: o Sagrado Alcorão, quase 100 recitadores, uma vasta coleção de livros, hadiths, súplicas diárias e ferramentas para progredir.","heroCta":"Descarregar gratuitamente","heroSecondary":"Explorar funcionalidades","heroNote":"Aplicação Android · Acesso gratuito · 8 idiomas de interface","heroBottom":"UM RECURSO PARA A SUA JORNADA","introKicker":"CONHECIMENTO, DE FORMA SIMPLES","introTitle":"Um espaço para<br><em>aprender ao seu ritmo.</em>","introText":"Desde a primeira versão, encontre mais de 23 livros e 16 grandes coleções completas de hadiths — quase 40 livros e coleções no total. Existem também cerca de 30 aulas áudio de estudiosos. A biblioteca continuará a crescer. Crie horários de estudo, ouça textos clássicos (mutun) e recitações e importe os seus próprios ficheiros áudio para o leitor integrado.","learnMore":"Saber mais","statSurahs":"recitadores disponíveis","statReadings":"leituras · Hafs e Warsh","statBooks":"livros e coleções","statCourses":"aulas áudio","statLanguages":"idiomas de interface","statPrice":"descarregamento gratuito","featuresKicker":"NA APLICAÇÃO","featuresTitle":"Recursos para<br><em>cada etapa.</em>","featuresLead":"Um ambiente pensado para ler, ouvir, estudar e memorizar.","fQuranTitle":"O Sagrado Alcorão","fQuranText":"Leia o Mushaf nas leituras Hafs e Warsh. Encontre suratas, marcadores e ferramentas de aprendizagem e revisão.","fBooksTitle":"Biblioteca de livros","fBooksText":"Explore livros e textos de várias disciplinas islâmicas.","fHadithTitle":"Hadiths e textos clássicos","fHadithText":"Explore 16 grandes coleções completas de hadiths, juntamente com textos de referência e recursos de estudo.","fAudioTitle":"Áudio e recitações","fAudioText":"Um leitor áudio completo: ouça textos clássicos (mutun), aulas de estudiosos reconhecidos e recitações; também pode importar os seus próprios ficheiros áudio.","fLangTitle":"Oito idiomas","fLangText":"Utilize a interface em árabe, francês, inglês, espanhol, alemão, português, turco e indonésio.","quoteText":"A regularidade na aprendizagem começa com um acesso simples aos recursos.","quoteCaption":"O SEU ESPAÇO DE ESTUDO","navSadaqa":"Sadaqah","fAdhkarTitle":"Adhkar e súplicas","fAdhkarText":"Encontre as súplicas diárias e a Fortaleza do Muçulmano para manter a lembrança de Allah.","fLearningTitle":"Aprender e rever","fLearningText":"Organize a memorização do Alcorão, guarde suratas e continue de onde parou.","fStudyTitle":"Ciências islâmicas","fStudyText":"Explore aqidah, fiqh, tajwid, língua árabe, adab e ciências do hadith.","fNawawiTitle":"Os 40 Hadiths de Nawawi","fNawawiText":"Estude ensinamentos fundamentais da religião através desta conhecida coleção.","sadaqaKicker":"UM PRESENTE PARA TODOS","sadaqaTitle":"O conhecimento deve ser partilhado.<br><em>Esta aplicação é uma sadaqah.</em>","sadaqaText":"الرسالة é gratuita por escolha. Foi criada para que todos possam aceder a recursos, aprender e progredir sem barreiras financeiras. Se lhe for útil, partilhe-a com outras pessoas.","sadaqaFoot":"Gratuita · Sem subscrição · Para todos","aboutKicker":"O NOSSO PROPÓSITO","aboutTitle":"Uma ferramenta simples,<br><em>ao serviço do conhecimento.</em>","aboutText":"الرسالة reúne ferramentas para ler o Alcorão, ouvir recitações, estudar livros e aprender ciências islâmicas. O projeto pretende tornar o conhecimento acessível ao maior número possível de pessoas.","aboutNote":"Por que é gratuita? Porque este projeto é uma sadaqah: um trabalho oferecido na esperança de beneficiar as pessoas, ajudá-las a aprender e continuar a gerar recompensa. Não é necessária subscrição nem pagamento para utilizar a aplicação.","aboutCta":"Obter a aplicação","downloadKicker":"COMECE HOJE","downloadTitle":"A sua biblioteca,<br><em>onde quer que vá.</em>","downloadText":"Descarregue gratuitamente a aplicação Android e tenha os seus recursos de estudo sempre consigo.","downloadCta":"Descarregar APK gratuito","versionLabel":"Versão","freeLabel":"Gratuito","installHint":"A transferência é fornecida através do GitHub Releases. O Android poderá pedir autorização para instalar aplicações desta origem.","faqKicker":"PRECISA DE AJUDA?","faqTitle":"Perguntas<br><em>frequentes.</em>","faqLead":"Algumas informações úteis antes da instalação.","faq1q":"A aplicação é gratuita? +","faq1a":"Sim, completamente. Toda a aplicação, todas as funcionalidades e conteúdos são gratuitos. Não existem subscrições, compras na aplicação nem versão premium. O apoio pelo Patreon é opcional e ajuda-me pessoalmente a criar outros projetos.","faq2q":"Como instalo o APK? +","faq2a":"Descarregue o APK na página GitHub Releases, abra-o no seu telemóvel Android e permita a instalação se o Android o solicitar.","faq3q":"A aplicação funciona offline? +","faq3a":"Algumas funcionalidades e recursos estão disponíveis localmente, enquanto conteúdos em streaming e determinados recursos exigem ligação à Internet.","faq4q":"Onde encontro novas versões? +","faq4a":"As atualizações são publicadas na secção Releases do repositório oficial do GitHub.","navSupport":"Apoiar","supportKicker":"APOIO OPCIONAL","supportTitle":"الرسالة é gratuita. <em>E continuará a ser.</em>","supportText":"A aplicação é totalmente gratuita: todas as funcionalidades e conteúdos estão disponíveis sem subscrição, pagamento ou plano premium. O Patreon não tem qualquer relação com o acesso à aplicação. Se decidir apoiar-me, a sua contribuição ajudar-me-á pessoalmente a criar outros projetos. É totalmente opcional.","supportPoint1":"Sem conteúdo pago","supportPoint2":"Sem funcionalidades exclusivas para apoiantes","supportPoint3":"Apoie apenas se desejar","supportCta":"Apoiar-me no Patreon","supportNote":"Obrigado pelo seu apoio. Nunca é necessário apoiar para utilizar الرسالة.","supportLinkMissing":"O link do Patreon será adicionado antes da publicação do site.","contactKicker":"AJUDE A MELHORAR O PROJETO","contactTitle":"Tem uma ideia para melhorar a aplicação?","contactText":"Tem uma ideia, sugestão ou encontrou um erro? Envie-me um e-mail a qualquer momento. O seu feedback vai ajudar-me a melhorar a aplicação.","contactCta":"Enviar uma ideia ou comunicar um erro","footerText":"Um espaço para ler, aprender e rever.","footerDownload":"Descarregar gratuitamente ↗","footerFree":"Projeto gratuito · Android","backTop":"Voltar ao topo ↑","fTafsirTitle":"Tafsir de cada versículo","fTafsirText":"Consulte a explicação dos versículos do Alcorão diretamente durante a leitura.","latestUpdate":"Última atualização: 0.21.8 — tafsir dos versículos do Alcorão e melhorias da aplicação."},
tr:{"navDiscover":"Keşfet","navFeatures":"Özellikler","navAbout":"Hakkında","navDownload":"İndir","eyebrow":"BİLGİ ELİNİZİN ALTINDA","heroTitle":"Oku. Dinle.<br><em>Öğren ve paylaş.</em>","heroLead":"Eksiksiz bir öğrenme alanı: Kur’an-ı Kerim, yaklaşık 100 okuyucu, geniş bir kitap koleksiyonu, hadisler, günlük dualar ve gelişmenize yardımcı araçlar.","heroCta":"Ücretsiz indir","heroSecondary":"Özellikleri keşfet","heroNote":"Android uygulaması · Ücretsiz erişim · 8 arayüz dili","heroBottom":"YOLCULUĞUNUZ İÇİN BİR KAYNAK","introKicker":"BİLGİ, KOLAYCA","introTitle":"Kendi hızınızda<br><em>öğrenmek için bir alan.</em>","introText":"İlk sürümden itibaren 23’ten fazla kitap ve 16 büyük hadis koleksiyonunun tamamını keşfedin; toplamda yaklaşık 40 kitap ve koleksiyon. Ayrıca âlimlerin yaklaşık 30 sesli dersi bulunur. Kütüphane büyümeye devam edecek. Çalışma programları oluşturun, klasik metinleri (mutun) ve tilavetleri dinleyin, kendi ses dosyalarınızı yerleşik oynatıcıya aktarın.","learnMore":"Daha fazla bilgi","statSurahs":"mevcut okuyucu","statReadings":"kıraat · Hafs ve Warsh","statBooks":"kitap ve koleksiyon","statCourses":"sesli ders","statLanguages":"arayüz dili","statPrice":"ücretsiz indirme","featuresKicker":"UYGULAMANIN İÇİNDE","featuresTitle":"Her aşama için<br><em>kaynaklar.</em>","featuresLead":"Okuma, dinleme, çalışma ve ezber için tasarlanmış bir ortam.","fQuranTitle":"Kur’an-ı Kerim","fQuranText":"Mushaf’ı Hafs ve Warsh kıraatleriyle okuyun. Surelerinize, yer imlerinize ve öğrenme/tekrar araçlarına ulaşın.","fBooksTitle":"Kitap kütüphanesi","fBooksText":"Farklı İslami ilim alanlarından kitapları ve metinleri keşfedin.","fHadithTitle":"Hadisler ve klasik metinler","fHadithText":"16 büyük hadis koleksiyonunu, temel kaynak metinleri ve çalışma materyallerini keşfedin.","fAudioTitle":"Ses ve tilavetler","fAudioText":"Eksiksiz bir ses oynatıcı: klasik metinleri (mutun), tanınmış âlimlerin derslerini ve tilavetleri dinleyin; kendi ses dosyalarınızı da aktarın.","fLangTitle":"Sekiz dil","fLangText":"Arayüzü Arapça, Fransızca, İngilizce, İspanyolca, Almanca, Portekizce, Türkçe ve Endonezce kullanın.","quoteText":"Öğrenmede devamlılık, kaynaklara kolay erişimle başlar.","quoteCaption":"ÇALIŞMA ALANINIZ","navSadaqa":"Sadaka","fAdhkarTitle":"Zikirler ve dualar","fAdhkarText":"Allah’ı anmayı sürdürmek için günlük duaları ve Hisnul Müslim’i bulun.","fLearningTitle":"Öğren ve tekrar et","fLearningText":"Kur’an ezberinizi düzenleyin, sureleri kaydedin ve kaldığınız yerden devam edin.","fStudyTitle":"İslami ilimler","fStudyText":"Akaid, fıkıh, tecvid, Arapça, edep ve hadis ilimlerini keşfedin.","fNawawiTitle":"Nevevî’nin 40 Hadisi","fNawawiText":"Bu tanınmış derleme aracılığıyla dinin temel öğretilerini öğrenin.","sadaqaKicker":"HERKES İÇİN BİR HEDİYE","sadaqaTitle":"Bilgi paylaşılmak içindir.<br><em>Bu uygulama bir sadakadır.</em>","sadaqaText":"الرسالة bilinçli olarak ücretsizdir. Herkesin maddi engel olmadan kaynaklara ulaşabilmesi, öğrenebilmesi ve ilerleyebilmesi için oluşturuldu. Faydalı bulursanız başkalarıyla paylaşın.","sadaqaFoot":"Ücretsiz · Abonelik yok · Herkes için","aboutKicker":"AMACIMIZ","aboutTitle":"Basit bir araç,<br><em>bilginin hizmetinde.</em>","aboutText":"الرسالة, Kur’an okumak, tilavet dinlemek, kitapları incelemek ve İslami ilimleri öğrenmek için araçları bir araya getirir. Proje, bilgiyi mümkün olduğunca çok kişiye ulaştırmayı amaçlar.","aboutNote":"Neden ücretsiz? Çünkü bu proje bir sadakadır: insanlara fayda sağlaması, öğrenmelerine yardımcı olması ve sevabının sürmesi umuduyla sunulmuştur. Uygulamaya erişmek için abonelik veya ödeme gerekmez.","aboutCta":"Uygulamayı edin","downloadKicker":"BUGÜN BAŞLAYIN","downloadTitle":"Kütüphaneniz,<br><em>her zaman yanınızda.</em>","downloadText":"Ücretsiz Android uygulamasını indirin ve çalışma kaynaklarınızı yanınızda taşıyın.","downloadCta":"Ücretsiz APK indir","versionLabel":"Sürüm","freeLabel":"Ücretsiz","installHint":"İndirme GitHub Releases üzerinden sağlanır. Android, bu kaynaktan yüklemeye izin vermenizi isteyebilir.","faqKicker":"YARDIMA MI İHTİYACINIZ VAR?","faqTitle":"Sıkça sorulan<br><em>sorular.</em>","faqLead":"Yüklemeden önce birkaç yararlı bilgi.","faq1q":"Uygulama ücretsiz mi? +","faq1a":"Evet, tamamen ücretsizdir. Uygulamanın tamamı, tüm özellikleri ve içerikleri ücretsizdir. Abonelik, uygulama içi satın alma veya premium sürüm yoktur. Patreon desteği isteğe bağlıdır ve kişisel olarak başka projeler oluşturmama yardımcı olur.","faq2q":"APK nasıl yüklenir? +","faq2a":"APK dosyasını GitHub Releases sayfasından indirin, Android telefonunuzda açın ve sistem isterse yüklemeye izin verin.","faq3q":"Uygulama çevrimdışı çalışır mı? +","faq3a":"Bazı özellikler ve kaynaklar yerel olarak kullanılabilir; yayın içerikleri ve bazı kaynaklar internet bağlantısı gerektirir.","faq4q":"Yeni sürümleri nerede bulabilirim? +","faq4a":"Güncellemeler resmi GitHub deposunun Releases bölümünde yayımlanır.","navSupport":"Destek ol","supportKicker":"İSTEĞE BAĞLI DESTEK","supportTitle":"الرسالة ücretsizdir. <em>Öyle kalacaktır.</em>","supportText":"Uygulama tamamen ücretsizdir: tüm özellikler ve içerikler abonelik, ödeme veya premium plan olmadan kullanılabilir. Patreon’un uygulamaya erişimle hiçbir ilgisi yoktur. Destek olmayı seçerseniz katkınız başka projeler oluşturmama kişisel olarak yardımcı olur. Tamamen isteğe bağlıdır.","supportPoint1":"Ücretli içerik yok","supportPoint2":"Destekçilere özel özellik yok","supportPoint3":"Yalnızca isterseniz destek olun","supportCta":"Patreon’da destek ol","supportNote":"Desteğiniz için teşekkür ederiz. الرسالة uygulamasını kullanmak için destek şart değildir.","supportLinkMissing":"Patreon bağlantısı site yayımlanmadan önce eklenecektir.","contactKicker":"PROJENİN GELİŞİMİNE KATKI SAĞLAYIN","contactTitle":"Uygulamayı geliştirmek için bir fikriniz var mı?","contactText":"Bir fikriniz, öneriniz veya bulduğunuz bir hata mı var? Dilediğiniz zaman e-posta gönderin. Geri bildiriminiz uygulamayı geliştirmeme yardımcı olur.","contactCta":"Fikir gönder veya hata bildir","footerText":"Okumak, öğrenmek ve tekrar etmek için bir alan.","footerDownload":"Ücretsiz indir ↗","footerFree":"Ücretsiz proje · Android","backTop":"Başa dön ↑","fTafsirTitle":"Her ayet için tefsir","fTafsirText":"Kur’an ayetlerinin açıklamasına okuma sırasında doğrudan ulaşın.","latestUpdate":"Son güncelleme: 0.21.8 — Kur’an ayetlerinin tefsiri ve uygulama iyileştirmeleri."},
id:{"navDiscover":"Jelajahi","navFeatures":"Fitur","navAbout":"Tentang","navDownload":"Unduh","eyebrow":"ILMU DALAM GENGGAMAN","heroTitle":"Baca. Dengarkan.<br><em>Pelajari dan bagikan.</em>","heroLead":"Ruang belajar lengkap: Al-Qur’an, hampir 100 qari, koleksi buku yang luas, hadis, doa harian, dan berbagai alat untuk membantu kemajuan belajar Anda.","heroCta":"Unduh gratis","heroSecondary":"Jelajahi fitur","heroNote":"Aplikasi Android · Akses gratis · 8 bahasa antarmuka","heroBottom":"SUMBER UNTUK PERJALANAN ANDA","introKicker":"ILMU, DENGAN MUDAH","introTitle":"Ruang untuk<br><em>belajar sesuai kecepatan Anda.</em>","introText":"Sejak versi pertama, tersedia lebih dari 23 buku dan 16 koleksi utama hadis yang lengkap — hampir 40 buku dan koleksi secara keseluruhan. Ada juga sekitar 30 pelajaran audio dari para ulama. Perpustakaan akan terus berkembang. Buat jadwal belajar, dengarkan matan klasik dan tilawah, serta impor berkas audio Anda ke pemutar bawaan.","learnMore":"Pelajari lebih lanjut","statSurahs":"qari tersedia","statReadings":"riwayat · Hafs & Warsh","statBooks":"buku dan koleksi","statCourses":"pelajaran audio","statLanguages":"bahasa antarmuka","statPrice":"unduhan gratis","featuresKicker":"DI DALAM APLIKASI","featuresTitle":"Sumber untuk<br><em>setiap langkah.</em>","featuresLead":"Lingkungan yang dirancang untuk membaca, mendengarkan, belajar, dan menghafal.","fQuranTitle":"Al-Qur’anul Karim","fQuranText":"Baca Mushaf dengan riwayat Hafs dan Warsh. Temukan surah, penanda halaman, serta alat belajar dan murajaah.","fBooksTitle":"Perpustakaan buku","fBooksText":"Jelajahi buku dan teks dari berbagai disiplin ilmu Islam.","fHadithTitle":"Hadis dan matan klasik","fHadithText":"Jelajahi 16 koleksi besar kitab hadis yang lengkap, beserta teks rujukan dan sumber untuk mempelajarinya.","fAudioTitle":"Audio dan tilawah","fAudioText":"Pemutar audio lengkap: dengarkan matan klasik, pelajaran audio para ulama, dan tilawah. Anda juga dapat mengimpor berkas audio sendiri.","fLangTitle":"Delapan bahasa","fLangText":"Gunakan antarmuka dalam bahasa Arab, Prancis, Inggris, Spanyol, Jerman, Portugis, Turki, dan Indonesia.","quoteText":"Konsistensi dalam belajar dimulai dengan akses mudah ke sumber ilmu.","quoteCaption":"RUANG BELAJAR ANDA","navSadaqa":"Sedekah","fAdhkarTitle":"Zikir dan doa","fAdhkarText":"Temukan doa harian dan Hisnul Muslim untuk menjaga ingatan kepada Allah.","fLearningTitle":"Belajar dan mengulang","fLearningText":"Atur hafalan Al-Qur’an, simpan surah, dan lanjutkan dari bagian terakhir.","fStudyTitle":"Ilmu-ilmu Islam","fStudyText":"Jelajahi akidah, fikih, tajwid, bahasa Arab, adab, dan ilmu hadis.","fNawawiTitle":"40 Hadis Nawawi","fNawawiText":"Pelajari ajaran dasar agama melalui kumpulan hadis yang terkenal ini.","sadaqaKicker":"HADIAH UNTUK SEMUA","sadaqaTitle":"Ilmu patut dibagikan.<br><em>Aplikasi ini adalah sedekah.</em>","sadaqaText":"الرسالة gratis atas pilihan kami. Aplikasi ini dibuat agar semua orang dapat mengakses sumber ilmu, belajar, dan berkembang tanpa hambatan biaya. Jika bermanfaat, bagikan kepada orang lain.","sadaqaFoot":"Gratis · Tanpa langganan · Untuk semua","aboutKicker":"TUJUAN KAMI","aboutTitle":"Alat sederhana,<br><em>untuk melayani ilmu.</em>","aboutText":"الرسالة menggabungkan alat untuk membaca Al-Qur’an, mendengarkan tilawah, mempelajari buku, dan belajar ilmu-ilmu Islam. Proyek ini bertujuan agar ilmu dapat diakses sebanyak mungkin orang.","aboutNote":"Mengapa gratis? Karena proyek ini adalah sedekah: karya yang diharapkan bermanfaat bagi orang lain, membantu mereka belajar, dan terus mendatangkan pahala. Tidak diperlukan langganan atau pembayaran untuk menggunakan aplikasi.","aboutCta":"Dapatkan aplikasi","downloadKicker":"MULAI HARI INI","downloadTitle":"Perpustakaan Anda,<br><em>ke mana pun Anda pergi.</em>","downloadText":"Unduh aplikasi Android gratis dan bawa sumber belajar Anda ke mana saja.","downloadCta":"Unduh APK gratis","versionLabel":"Versi","freeLabel":"Gratis","installHint":"Unduhan tersedia melalui GitHub Releases. Android mungkin meminta izin untuk memasang aplikasi dari sumber ini.","faqKicker":"BUTUH BANTUAN?","faqTitle":"Pertanyaan<br><em>yang sering diajukan.</em>","faqLead":"Beberapa informasi berguna sebelum memasang.","faq1q":"Apakah aplikasi ini gratis? +","faq1a":"Ya, sepenuhnya gratis. Seluruh aplikasi, semua fitur, dan kontennya gratis. Tidak ada langganan, pembelian dalam aplikasi, atau versi premium. Dukungan Patreon bersifat opsional dan hanya membantu saya membuat proyek lain secara pribadi.","faq2q":"Bagaimana cara memasang APK? +","faq2a":"Unduh APK dari halaman GitHub Releases, buka di ponsel Android Anda, lalu izinkan pemasangan jika Android memintanya.","faq3q":"Apakah aplikasi dapat digunakan offline? +","faq3a":"Beberapa fitur dan sumber tersedia secara lokal, sedangkan konten streaming dan sumber tertentu memerlukan koneksi internet.","faq4q":"Di mana saya dapat menemukan versi baru? +","faq4a":"Pembaruan diterbitkan di bagian Releases pada repositori GitHub resmi.","navSupport":"Dukung","supportKicker":"DUKUNGAN OPSIONAL","supportTitle":"الرسالة gratis. <em>Dan akan tetap gratis.</em>","supportText":"Aplikasi ini sepenuhnya gratis: semua fitur dan konten tersedia tanpa langganan, pembayaran, atau paket premium. Patreon sama sekali tidak berkaitan dengan akses aplikasi. Jika Anda memilih untuk mendukung saya, kontribusi Anda akan membantu saya membuat proyek lain. Dukungan ini sepenuhnya opsional.","supportPoint1":"Tidak ada konten berbayar","supportPoint2":"Tidak ada fitur khusus donatur","supportPoint3":"Dukung hanya jika Anda ingin","supportCta":"Dukung saya di Patreon","supportNote":"Terima kasih atas dukungan Anda. Dukungan tidak pernah diwajibkan untuk menggunakan الرسالة.","supportLinkMissing":"Tautan Patreon akan ditambahkan sebelum situs diterbitkan.","contactKicker":"BANTU KEMBANGKAN PROYEK INI","contactTitle":"Punya ide untuk meningkatkan aplikasi?","contactText":"Punya ide, saran, atau menemukan bug? Kirim email kapan saja. Masukan Anda akan membantu saya meningkatkan aplikasi.","contactCta":"Kirim ide atau laporkan bug","footerText":"Ruang untuk membaca, belajar, dan mengulang.","footerDownload":"Unduh gratis ↗","footerFree":"Proyek gratis · Android","backTop":"Kembali ke atas ↑","fTafsirTitle":"Tafsir setiap ayat","fTafsirText":"Baca penjelasan ayat-ayat Al-Qur’an langsung saat membaca.","latestUpdate":"Pembaruan terakhir: 0.21.8 — tafsir ayat-ayat Al-Qur’an dan peningkatan aplikasi."}
};
const languageSelect=document.getElementById('languageSelect');
function setLanguage(lang){const dict=translations[lang]||translations.en;document.documentElement.lang=lang;document.body.dir=(lang==='ar'||lang==='ur')?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(dict[key]!==undefined)el.innerHTML=dict[key]});languageSelect.value=lang;try{localStorage.setItem('risalah-site-language',lang)}catch(e){}}
languageSelect.addEventListener('change',e=>setLanguage(e.target.value));
document.getElementById('year').textContent=new Date().getFullYear();
const cfg=window.SITE_CONFIG||{};const patreonButton=document.getElementById('patreonButton');if(patreonButton&&cfg.patreonUrl&&cfg.patreonUrl!=='AJOUTER-ICI-VOTRE-LIEN-PATREON'){patreonButton.href=cfg.patreonUrl;}else if(patreonButton){patreonButton.addEventListener('click',e=>{e.preventDefault();alert((translations[languageSelect.value]||translations.en).supportLinkMissing);});}const contactButton=document.getElementById('contactEmailButton');if(contactButton&&cfg.contactEmail&&cfg.contactEmail!=='VOTRE-ADRESSE-E-MAIL'){contactButton.href='mailto:'+cfg.contactEmail;}if(cfg.appVersion)document.getElementById('appVersion').textContent=cfg.appVersion;const downloadTargets=['downloadButton'];if(cfg.apkUrl){downloadTargets.forEach(id=>{const el=document.getElementById(id);if(el)el.href=cfg.apkUrl;});}
const iosButton=document.getElementById('iosButton');if(iosButton){if(cfg.iosUrl){iosButton.href=cfg.iosUrl;iosButton.target='_blank';iosButton.rel='noopener';}else{iosButton.addEventListener('click',e=>{e.preventDefault();alert((translations[languageSelect.value]||translations.fr).iosSoon);});}}
const toggle=document.getElementById('menuToggle');const nav=document.querySelector('.desktop-nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));
let initialLanguage='en';try{const saved=localStorage.getItem('risalah-site-language');if(saved&&translations[saved])initialLanguage=saved;}catch(e){}setLanguage(initialLanguage);
